INSERT INTO hashtags (tag) SELECT DISTINCT lower(r.m[2]) FROM workout_posts p CROSS JOIN LATERAL regexp_matches(p.caption, '(^|[^[:alnum:]_&#])#([[:alnum:]_]+)', 'g') AS r(m) WHERE p.user_id IN ('d63d873b-cc9b-5424-b593-328be19fc4e8', '6229fb30-d7ad-5aa4-841e-b8536f14dfb3', 'aa4d293e-851c-5943-a1ed-f3f1afa447b2', '2742934a-ced9-57d0-a634-4338099ee102', '4a0ca4f3-e493-5e56-83f0-788e055ba8e3', 'aa9f3faa-a898-56bf-953e-55551be50449', '19ba4c03-9156-5097-8665-2e002acaf98a', '937f441f-2ced-5dab-86cc-eba53797e39d') ON CONFLICT (tag) DO NOTHING;
INSERT INTO workout_post_hashtags (workout_post_id, hashtag_id) SELECT DISTINCT p.id, h.id FROM workout_posts p CROSS JOIN LATERAL regexp_matches(p.caption, '(^|[^[:alnum:]_&#])#([[:alnum:]_]+)', 'g') AS r(m) JOIN hashtags h ON h.tag = lower(r.m[2]) WHERE p.user_id IN ('d63d873b-cc9b-5424-b593-328be19fc4e8', '6229fb30-d7ad-5aa4-841e-b8536f14dfb3', 'aa4d293e-851c-5943-a1ed-f3f1afa447b2', '2742934a-ced9-57d0-a634-4338099ee102', '4a0ca4f3-e493-5e56-83f0-788e055ba8e3', 'aa9f3faa-a898-56bf-953e-55551be50449', '19ba4c03-9156-5097-8665-2e002acaf98a', '937f441f-2ced-5dab-86cc-eba53797e39d') ON CONFLICT DO NOTHING;
